class Solution:
    def maxIntersectionCount(self, y):
        vals = sorted(set(y))
        idx = {v: i for i, v in enumerate(vals)}
        m = len(vals)
        diff = [0] * (m + 1)
        for i in range(len(y) - 1):
            u, v = y[i], y[i + 1]
            if u > v: u, v = v, u
            diff[idx[u] + 1] += 1
            diff[idx[v]] -= 1
        bonus = [0] * m
        n = len(y)
        for i in range(n):
            lo = i == 0 or y[i - 1] > y[i]
            hi = i == n - 1 or y[i + 1] > y[i]
            if lo != hi:
                bonus[idx[y[i]]] += 1
        cur = best = 0
        for i in range(m):
            cur += diff[i]
            best = max(best, cur + bonus[i])
        return best

