class Solution {
public:
    int maxIntersectionCount(vector<int>& y) {
        vector<int> vals = y;
        sort(vals.begin(), vals.end());
        vals.erase(unique(vals.begin(), vals.end()), vals.end());
        unordered_map<int,int> idx;
        for (int i = 0; i < (int)vals.size(); i++) idx[vals[i]] = i;
        int m = vals.size(), n = y.size();
        vector<int> diff(m + 1, 0), bonus(m, 0);
        for (int i = 0; i + 1 < n; i++) {
            int u = y[i], v = y[i + 1];
            if (u > v) swap(u, v);
            diff[idx[u] + 1]++; diff[idx[v]]--;
        }
        for (int i = 0; i < n; i++) {
            bool lo = (i == 0) || y[i - 1] > y[i];
            bool hi = (i == n - 1) || y[i + 1] > y[i];
            if (lo != hi) bonus[idx[y[i]]]++;
        }
        int cur = 0, best = 0;
        for (int i = 0; i < m; i++) {
            cur += diff[i];
            best = max(best, cur + bonus[i]);
        }
        return best;
    }
};

