class Solution {
    public int maxIntersectionCount(int[] y) {
        int[] vals = y.clone();
        Arrays.sort(vals);
        int m = 0;
        for (int i = 0; i < vals.length; i++)
            if (i == 0 || vals[i] != vals[i - 1]) vals[m++] = vals[i];
        Map<Integer,Integer> idx = new HashMap<>();
        for (int i = 0; i < m; i++) idx.put(vals[i], i);
        int n = y.length;
        int[] diff = new int[m + 1], bonus = new int[m];
        for (int i = 0; i + 1 < n; i++) {
            int u = y[i], v = y[i + 1];
            if (u > v) { int t = u; u = v; v = t; }
            diff[idx.get(u) + 1]++; diff[idx.get(v)]--;
        }
        for (int i = 0; i < n; i++) {
            boolean lo = (i == 0) || y[i - 1] > y[i];
            boolean hi = (i == n - 1) || y[i + 1] > y[i];
            if (lo != hi) bonus[idx.get(y[i])]++;
        }
        int cur = 0, best = 0;
        for (int i = 0; i < m; i++) {
            cur += diff[i];
            best = Math.max(best, cur + bonus[i]);
        }
        return best;
    }
}

