var maxIntersectionCount = function(y) {
    const vals = [...new Set(y)].sort((a, b) => a - b);
    const idx = new Map(vals.map((v, i) => [v, i]));
    const m = vals.length, n = y.length;
    const diff = new Array(m + 1).fill(0), bonus = new Array(m).fill(0);
    for (let i = 0; i + 1 < n; i++) {
        let u = y[i], v = y[i + 1];
        if (u > v) [u, v] = [v, u];
        diff[idx.get(u) + 1]++; diff[idx.get(v)]--;
    }
    for (let i = 0; i < n; i++) {
        const lo = i === 0 || y[i - 1] > y[i];
        const hi = i === n - 1 || y[i + 1] > y[i];
        if (lo !== hi) bonus[idx.get(y[i])]++;
    }
    let cur = 0, best = 0;
    for (let i = 0; i < m; i++) {
        cur += diff[i];
        best = Math.max(best, cur + bonus[i]);
    }
    return best;
};
